const toneMap: Record<string, string> = { Disetujui: "bg-[#e2f0dd] text-[#507343]", Diproses: "bg-[#fff0d8] text-[#9b6b22]", Draft: "bg-[#eceeea] text-[#687168]", Arsip: "bg-[#ece8f0] text-[#6c5875]", Aktif: "bg-[#e2f0dd] text-[#507343]", "Perlu perbaikan": "bg-[#fff0d8] text-[#9b6b22]", Rusak: "bg-[#f9e0dc] text-[#a84b40]", Baik: "bg-[#e2f0dd] text-[#507343]" };

function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: React.ReactNode; description: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-[11px] font-bold uppercase tracking-[0.2em] text-[#ed8c6f]">{eyebrow}</p><h1 className="font-serif text-3xl font-bold tracking-[-0.03em] text-[#243b32] sm:text-[38px]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#7c837b]">{description}</p></div>{action}</div>;
}
function Status({ value }: { value: string }) { return <span className={cn("inline-flex rounded-full px-2.5 py-1 text-[10px] font-bold", toneMap[value] || "bg-[#eceeea] text-[#687168]")}>{value}</span>; }
function SectionLink({ href, children }: { href: string; children: React.ReactNode }) { return <Link href={href} className="inline-flex items-center gap-1 text-xs font-bold text-[#6d7b70] hover:text-[#243b32]">{children}<ChevronRight className="h-3.5 w-3.5" /></Link>; }
function StatCard({ label, value, note, icon: Icon, accent, href }: { label: string; value: string | number; note: string; icon: typeof Users; accent: string; href?: string }) { const inner = <Card className="group relative overflow-hidden rounded-[20px] border-0 bg-white shadow-[0_4px_24px_rgba(31,48,36,0.055)] transition-all hover:-translate-y-0.5 hover:shadow-[0_10px_30px_rgba(31,48,36,0.09)]"><div className={cn("absolute right-0 top-0 h-24 w-24 translate-x-8 -translate-y-8 rounded-full opacity-80", accent)} /><CardContent className="relative p-5"><div className="mb-5 flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f4f5f1] text-[#52665a]"><Icon className="h-[18px] w-[18px]" /></div><ArrowUpRight className="h-4 w-4 text-[#bac0b8] transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" /></div><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-[#899188]">{label}</p><div className="mt-1 flex items-end gap-2"><p className="font-serif text-[30px] font-bold leading-none text-[#243b32]">{value}</p><span className="mb-0.5 text-[10px] font-semibold text-[#80a36e]">{note}</span></div></CardContent></Card>; return href ? <Link href={href}>{inner}</Link> : inner; }

